package main

import "fmt"

func increment(n *int) {
	*n += 1
}

func clearLocal(n *int) {
	n = nil
	fmt.Println("local pointer is nil:", n == nil)
}

func main() {
	count := 2
	first := &count
	second := first

	increment(first)
	fmt.Println(count, *second, first == second)

	clearLocal(first)
	fmt.Println("caller pointer still works:", *first)
}
