type Counter struct {
	value int
}

func (c Counter) Value() int {
	return c.value
}

func (c *Counter) Add(delta int) {
	c.value += delta
}

func main() {
	counter := Counter{value: 2}
	counter.Add(3)
	fmt.Println(counter.Value())
}
