package main

import "fmt"

type User struct {
	Name string
}

func inspect(value any) {
	fmt.Println("interface is nil:", value == nil)
	user, ok := value.(*User)
	fmt.Println("contains nil *User:", ok && user == nil)
}

func main() {
	var user *User
	var value any = user

	fmt.Println("pointer is nil:", user == nil)
	inspect(value)

	if user != nil {
		fmt.Println(user.Name)
	}
}
