package main

import "fmt"

type Profile struct {
	Name string
	Tags []string
}

func changeValue(profile Profile) {
	profile.Name = "value copy"
	profile.Tags[0] = "shared backing array"
}

func changePointer(profile *Profile) {
	profile.Name = "pointer update"
}

func main() {
	profile := Profile{Name: "Ada", Tags: []string{"go"}}

	changeValue(profile)
	fmt.Println(profile.Name, profile.Tags[0])

	changePointer(&profile)
	fmt.Println(profile.Name, profile.Tags[0])
}
