package pointerlesson

import (
	"errors"
	"testing"
)

type User struct {
	Name string
}

func displayName(user *User) (string, error) {
	if user == nil {
		return "", errors.New("user is missing")
	}
	return user.Name, nil
}

func containsNilUser(value any) bool {
	user, ok := value.(*User)
	return ok && user == nil
}

func TestNilBoundaries(t *testing.T) {
	name, err := displayName(&User{Name: "Ada"})
	if err != nil || name != "Ada" {
		t.Fatalf("valid user: name=%q err=%v", name, err)
	}

	if _, err := displayName(nil); err == nil {
		t.Fatal("nil user should return an error")
	}

	var user *User
	var value any = user
	if value == nil || !containsNilUser(value) {
		t.Fatal("expected a non-nil interface containing a nil *User")
	}
}
